 public function test_legacy_ai_core_uses_product_defaults_and_existing_agent_fills_slot():void{[$t]=$this->tenant('legacy');DB::table('ai_agents')->insert(['tenant_id'=>$t->id,'status'=>'active']);$c=app(AiCapacityService::class);$this->assertSame([1,1,0,1000,100,250],[$c->limit($t,AiCapacityService::MAX_AGENTS),$c->limit($t,AiCapacityService::MAX_WEBCHAT_CHANNELS),$c->limit($t,AiCapacityService::MAX_WHATSAPP_CHANNELS),$c->limit($t,AiCapacityService::MONTHLY_RUNTIME_UNITS),$c->limit($t,AiCapacityService::MONTHLY_ACTION_RUNS),$c->limit($t,AiCapacityService::MONTHLY_CONVERSATIONS)]);$this->assertSame(1,$c->used($t,AiCapacityService::MAX_AGENTS));$this->expectException(AiCapacityExceededException::class);DB::transaction(fn()=>$c->assertResourceAvailable($t,AiCapacityService::MAX_AGENTS));}
 public function test_plan_addons_disabled_addon_and_override_have_deterministic_precedence():void{[$t,$s,$e,$plan,$module]=$this->tenant('formula');DB::table('network_plan_module_capacities')->insert(['plan_id'=>$plan,'module_id'=>$module,'capability_code'=>AiCapacityService::MAX_AGENTS,'quantity'=>1,'created_at'=>now(),'updated_at'=>now()]);$p=app(AiCapacityProvisioningService::class);$p->addon($e,AiCapacityService::MAX_AGENTS,'a',1);$p->addon($e,AiCapacityService::MAX_AGENTS,'disabled',2,false);$this->assertSame(2,app(AiCapacityService::class)->limit($t,AiCapacityService::MAX_AGENTS));$p->override($e,AiCapacityService::MAX_AGENTS,5);$this->assertSame(6,app(AiCapacityService::class)->limit($t,AiCapacityService::MAX_AGENTS));$p->override($e,AiCapacityService::MAX_AGENTS,7,false);$this->assertSame(2,app(AiCapacityService::class)->limit($t,AiCapacityService::MAX_AGENTS));$this->assertSame(1,DB::table('network_entitlement_capacities')->where('source','override')->count());}
 public function test_retired_agent_releases_capacity_without_deletion():void{[$t]=$this->tenant('retired');$id=DB::table('ai_agents')->insertGetId(['tenant_id'=>$t->id,'status'=>'active']);$c=app(AiCapacityService::class);$this->assertSame(1,$c->used($t,AiCapacityService::MAX_AGENTS));DB::table('ai_agents')->where('id',$id)->update(['status'=>'retired']);$this->assertSame(0,$c->used($t,AiCapacityService::MAX_AGENTS));$this->assertDatabaseHas('ai_agents',['id'=>$id,'status'=>'retired']);DB::transaction(fn()=>$c->assertResourceAvailable($t,AiCapacityService::MAX_AGENTS));}
 public function test_usage_is_idempotent_and_separate_for_every_metric():void{[$t]=$this->tenant('usage');$c=app(AiCapacityService::class);foreach([[AiCapacityService::MONTHLY_RUNTIME_UNITS,'runtime_run:10'],[AiCapacityService::MONTHLY_ACTION_RUNS,'action_run:20'],[AiCapacityService::MONTHLY_CONVERSATIONS,'conversation:30']]as[$cap,$key]){DB::transaction(fn()=>$c->consume($t,$cap,$key));DB::transaction(fn()=>$c->consume($t,$cap,$key));$this->assertSame(1,DB::table('network_usage_events')->where('tenant_id',$t->id)->where('metric',AiCapacityService::METRICS[$cap])->count());}}
 public function test_monthly_bucket_is_half_open_resets_and_handles_january_anchor():void{CarbonImmutable::setTestNow('2028-01-31 10:00:00');[$t,$s]=$this->tenant('period','2028-01-31 10:00:00','2029-01-31 10:00:00');$c=app(AiCapacityService::class);DB::table('network_usage_events')->insert([['uuid'=>'00000000-0000-0000-0000-000000000001','tenant_id'=>$t->id,'subscription_id'=>$s->id,'metric'=>'ai_runtime_units','quantity'=>1,'idempotency_key'=>'old','occurred_at'=>'2028-01-31 10:00:00','created_at'=>now()]]);$this->assertSame(1,$c->used($t,AiCapacityService::MONTHLY_RUNTIME_UNITS));CarbonImmutable::setTestNow('2028-02-29 09:59:59');$this->assertSame(1,$c->used($t,AiCapacityService::MONTHLY_RUNTIME_UNITS));CarbonImmutable::setTestNow('2028-02-29 10:00:00');$this->assertSame(0,$c->used($t,AiCapacityService::MONTHLY_RUNTIME_UNITS));$period=app(AiUsagePeriodResolver::class)->current($s->fresh());$this->assertSame('2028-02-29 10:00:00',$period->start->format('Y-m-d H:i:s'));$this->assertSame('2028-03-31 10:00:00',$period->end->format('Y-m-d H:i:s'));}
 public function test_extending_same_subscription_does_not_carry_previous_month_usage():void{CarbonImmutable::setTestNow('2028-01-15 00:00:00');[$t,$s]=$this->tenant('renew','2028-01-01','2028-02-01');DB::table('network_usage_events')->insert(['uuid'=>'00000000-0000-0000-0000-000000000002','tenant_id'=>$t->id,'subscription_id'=>$s->id,'metric'=>'ai_conversations','quantity'=>3,'idempotency_key'=>'jan','occurred_at'=>'2028-01-15','created_at'=>now()]);DB::table('network_subscriptions')->where('id',$s->id)->update(['current_period_end'=>'2028-04-01']);CarbonImmutable::setTestNow('2028-02-01 00:00:00');$this->assertSame(0,app(AiCapacityService::class)->used($t,AiCapacityService::MONTHLY_CONVERSATIONS));}
 public function test_missing_disabled_or_expired_ai_authority_grants_zero():void{[$missing]=$this->tenant('missing',null,null,false);$this->assertSame(0,app(AiCapacityService::class)->limit($missing,AiCapacityService::MAX_AGENTS));[$disabled,$s,$e]=$this->tenant('disabled');$e->update(['is_enabled'=>false]);$this->assertSame(0,app(AiCapacityService::class)->limit($disabled,AiCapacityService::MAX_AGENTS));CarbonImmutable::setTestNow('2030-01-02');[$expired]=$this->tenant('expired','2029-01-01','2030-01-01');$this->assertSame(0,app(AiCapacityService::class)->limit($expired,AiCapacityService::MAX_AGENTS));}
 public function test_global_feature_and_inactive_tenant_fail_closed():void{[$tenant]=$this->tenant('gates');$capacity=app(AiCapacityService::class);config(['ai.enabled'=>false]);$this->assertSame(0,$capacity->limit($tenant,AiCapacityService::MAX_AGENTS));config(['ai.enabled'=>true]);DB::table('network_tenants')->where('id',$tenant->id)->update(['status'=>'inactive']);$this->assertSame(0,$capacity->limit($tenant->fresh(),AiCapacityService::MAX_AGENTS));}
 public function test_composite_foreign_keys_reject_cross_tenant_and_cross_subscription_rows():void{[$a,$sa,$ea]=$this->tenant('a');[$b,$sb]=$this->tenant('b');foreach([['tenant_id'=>$b->id,'subscription_id'=>$sa->id,'entitlement_id'=>$ea->id],['tenant_id'=>$a->id,'subscription_id'=>$sb->id,'entitlement_id'=>$ea->id]]as$bad){try{DB::table('network_entitlement_capacities')->insert($bad+['capability_code'=>AiCapacityService::MAX_AGENTS,'quantity'=>1,'source'=>'addon','source_key'=>uniqid(),'is_enabled'=>true,'created_at'=>now(),'updated_at'=>now()]);$this->fail('Incoherent capacity accepted.');}catch(QueryException){$this->addToAssertionCount(1);}}}
 public function test_plan_capacity_requires_existing_plan_module_relation():void{[$t,$s,$e,$plan]=$this->tenant('plan-integrity');$other=DB::table('network_modules')->insertGetId(['code'=>'OTHER','name'=>'Other']);$this->expectException(QueryException::class);DB::table('network_plan_module_capacities')->insert(['plan_id'=>$plan,'module_id'=>$other,'capability_code'=>AiCapacityService::MAX_AGENTS,'quantity'=>1,'created_at'=>now(),'updated_at'=>now()]);}
 public function test_migration_is_sqlite_reversible_and_identifiers_fit_mysql():void{$this->migration->down();$this->assertFalse(Schema::hasTable('network_entitlement_capacities'));$this->migration->up();$this->assertTrue(Schema::hasTable('network_entitlement_capacities'));foreach(['net_sub_tenant_id_uq','net_ent_owner_id_uq','net_plan_mod_cap_uq','net_plan_mod_cap_rel_fk','net_ent_cap_source_uq','net_ent_cap_lookup_idx','net_ent_cap_sub_fk','net_ent_cap_ent_fk']as$n)$this->assertLessThanOrEqual(64,strlen($n));}
 private function tenant(string$code,?string$start=null,?string$end=null,bool$ai=true):array{$start??=now()->subDay()->format('Y-m-d H:i:s');$end??=now()->addYear()->format('Y-m-d H:i:s');$id=DB::table('network_tenants')->insertGetId(['uuid'=>str_pad($code,36,'0'),'code'=>$code,'name'=>$code,'status'=>'active']);$plan=DB::table('network_plans')->insertGetId(['code'=>'P-'.$code,'name'=>'Plan']);$module=DB::table('network_modules')->insertGetId(['code'=>'AI_CORE-'.$code,'name'=>'AI']);DB::table('network_plan_modules')->insert(['plan_id'=>$plan,'module_id'=>$module,'is_included'=>true]);$sid=DB::table('network_subscriptions')->insertGetId(['uuid'=>str_pad('s'.$code,36,'0'),'tenant_id'=>$id,'plan_id'=>$plan,'status'=>'active','started_at'=>$start,'current_period_start'=>$start,'current_period_end'=>$end]);$eid=null;if($ai)$eid=DB::table('network_entitlements')->insertGetId(['subscription_id'=>$sid,'tenant_id'=>$id,'module_id'=>$module,'code'=>'AI_CORE','is_enabled'=>true]);$t=Tenant::query()->findOrFail($id);app(TenantContext::class)->set($t);return[$t,Subscription::findOrFail($sid),$eid?Entitlement::findOrFail($eid):null,$plan,$module];}
